@param string|\Discord\Parts\Channel\Message\Message|null $options ['after']  Get messages after this message ID.
@param int|null $options ['limit']  Max number of messages to return (1-100). Defaults to 50.
@return \React\Promise\PromiseInterface<\Discord\Helpers\ExCollectionInterface<\Discord\Parts\Channel\Message\Message>|\Discord\Parts\Channel\Message\Message[]>
@since 10.66.2

